INSERT INTO public.cd_professions (profession_id, career_area_id, title_sv, title_en, career_stage, entry_role, regulated, transition_difficulty, review_state, derived_from_area, approved_for_ranking, cig_profession_slug, inclusion_rationale_sv, inclusion_rationale_en, limitation_note_sv, limitation_note_en)
VALUES
  ('SP001', 'SCA01', 'Väktare', 'Security Officer (Väktare)', 'entry', true, true, 1, 'ai_researched', false, false, 'vaktare', 'Ditt svarsmönster visar ett tydligt drag mot praktiskt, situationsnära arbete kombinerat med riskmedvetenhet och strukturerad dokumentation -- kärnan i en väktarroll.', 'Your answers show a clear pull toward practical, situation-near work combined with risk awareness and structured documentation -- the core of a security-officer role.', NULL, NULL),
  ('SP002', 'SCA02', 'Ordningsvakt', 'Public Order Guard', 'entry', true, true, 3, 'ai_researched', false, false, 'ordningsvakt', 'Du kombinerar operativ handlingskraft med förmåga att hantera motstånd och sätta gränser -- centralt i ordningsvaktsrollen, som ofta innebär direkt konflikthantering i publika miljöer.', 'You combine operational drive with comfort handling resistance and setting boundaries -- central to a public-order-guard role, which often involves direct conflict handling in public settings.', 'Kräver godkännande och förordnande via Polismyndigheten; inte en anställning man börjar direkt utan process.', 'Requires approval and commissioning via the Swedish Police Authority; not a role you start without that process.'),
  ('SP003', 'SCA01', 'Skyddsvakt', 'Protective Security Guard', 'entry', true, true, 2, 'ai_researched', false, false, 'skyddsvakt', 'Din höga riskmedvetenhet tillsammans med struktur och självständigt beslutsfattande passar väl med skyddsvaktens roll att skydda skyddsobjekt enligt skyddslagen.', 'Your high risk awareness combined with structure and independent decision-making fits well with a protective-security-guard''s role safeguarding protected sites under the Protective Security Act.', 'Godkännande sker via länsstyrelsen efter registerkontroll; en process, inte en direktanställning.', 'Approval runs through the county administrative board after a background check; a process, not a direct hire.'),
  ('SP004', 'SCA01', 'Personskyddsvakt', 'Close Protection Officer', 'developing', false, true, 4, 'ai_researched', false, false, 'personskyddsvakt', 'Din kombination av konflikthantering, självständiga beslut under press och lugn i pressade lägen matchar personskyddets krav på ständig vaksamhet och snabba avgöranden.', 'Your combination of conflict handling, independent decisions under pressure and composure matches close protection''s demand for constant vigilance and fast judgement.', 'Vanligtvis en tilläggsutbildning efter minst två års väktarerfarenhet, inte en förstajobbsroll.', 'Typically an add-on qualification after at least two years as a security officer, not a first job.'),
  ('SP005', 'SCA02', 'Polis', 'Police Officer', 'entry', true, true, 5, 'ai_researched', false, false, 'polis', 'Ditt mönster av serviceorientering, konflikthantering, självständigt beslutsfattande och lugn under press liknar den bredd som polisyrket kräver i det dagliga arbetet.', 'Your pattern of service orientation, conflict handling, independent decision-making and composure resembles the breadth policing calls for day to day.', 'Kräver antagning till polisutbildningen (grundutbildning + aspirantutbildning) och uppfyllda behörighetskrav.', 'Requires admission to police training (basic training plus a supervised probationary period) and meeting eligibility requirements.'),
  ('SP006', 'SCA04', 'Säkerhetssamordnare', 'Security Coordinator', 'developing', false, false, 3, 'ai_researched', false, false, 'sakerhetssamordnare', 'Du visar en kombination av ledarskapsintresse, tydlig kommunikation och strukturerat arbetssätt -- precis det som krävs för att samordna säkerhetsarbete mellan flera team och funktioner.', 'You show a combination of leadership interest, clear communication and structured working -- exactly what''s needed to coordinate security work across teams and functions.', NULL, NULL),
  ('SP007', 'SCA04', 'Säkerhetschef', 'Head of Security', 'senior', false, false, 6, 'ai_researched', false, false, 'sakerhetschef', 'Din profil visar starka signaler för ledarskap, strategiskt tänkande och kommunikation -- egenskaper som väger tungt när säkerhetsarbete ska styras på organisationsnivå.', 'Your profile shows strong leadership, strategic thinking and communication signals -- qualities that matter most when security work is governed at an organisational level.', 'Normalt en roll man växer in i efter flera års erfarenhet i operativa eller samordnande säkerhetsroller, sällan ett förstajobb.', 'Normally a role grown into after several years in operational or coordinating security roles, rarely a first job.'),
  ('SP008', 'SCA09', 'SOC-analytiker', 'SOC Analyst', 'entry', true, false, 3, 'ai_researched', false, false, 'soc-analytiker', 'Ditt analytiska och tekniska intresse, tillsammans med utredande läggning, matchar arbetet i ett Security Operations Center: att upptäcka, granska och agera på avvikelser i realtid.', 'Your analytical and technical interest, combined with an investigative streak, matches SOC work: detecting, examining and acting on anomalies in real time.', NULL, NULL),
  ('SP009', 'SCA09', 'Cybersäkerhetsanalytiker', 'Cybersecurity Analyst', 'developing', false, false, 4, 'ai_researched', false, false, 'cybersakerhetsanalytiker', 'Din tekniska och analytiska profil, i kombination med lärandeorientering, passar en roll som kräver att ligga steget före ständigt föränderliga hot mot informationstillgångar.', 'Your technical and analytical profile, combined with a drive to keep learning, fits a role that requires staying ahead of constantly changing threats to information assets.', NULL, NULL),
  ('SP010', 'SCA06', 'Säkerhetsutredare', 'Security Investigator', 'developing', false, false, 4, 'ai_researched', false, false, 'sakerhetsutredare', 'Ditt starka utredande drag, analytiska förmåga och strukturerade arbetssätt är precis det som krävs för att granska, verifiera och fastställa vad som faktiskt hänt.', 'Your strong investigative streak, analytical ability and structured way of working are exactly what''s needed to examine, verify and establish what actually happened.', NULL, NULL),
  ('SP011', 'SCA05', 'Riskchef', 'Risk Manager', 'senior', false, false, 6, 'ai_researched', false, false, 'risk-manager', 'Din analytiska och strategiska läggning, tillsammans med hög riskmedvetenhet, pekar mot en roll där du bedömer och prioriterar risk på organisationsnivå.', 'Your analytical and strategic bent, combined with high risk awareness, points toward a role assessing and prioritising risk at an organisational level.', 'Normalt en roll för den med flera års erfarenhet av riskarbete, sällan ett förstajobb.', 'Normally a role for someone with several years of risk-related experience, rarely a first job.'),
  ('SP012', 'SCA05', 'Krisberedskapssamordnare', 'Crisis Preparedness Coordinator', 'developing', false, false, 4, 'ai_researched', false, false, 'krisberedskapssamordnare', 'Din förmåga att samarbeta brett, tänka framåt och hålla huvudet kallt matchar arbetet med att förbereda organisationer för kriser innan de inträffar.', 'Your ability to collaborate broadly, think ahead and stay composed matches the work of preparing organisations for crises before they happen.', NULL, NULL),
  ('SP013', 'SCA07', 'AML-specialist', 'AML Specialist', 'developing', false, false, 4, 'ai_researched', false, false, 'aml-specialist', 'Din analytiska och utredande läggning, tillsammans med strukturerat arbetssätt, matchar arbetet med att granska transaktioner och identifiera misstänkta mönster.', 'Your analytical and investigative bent, combined with structured working, matches the work of reviewing transactions and identifying suspicious patterns.', NULL, NULL),
  ('SP014', 'SCA03', 'Säkerhetstekniker', 'Security Technician', 'entry', true, false, 3, 'ai_researched', false, false, 'sakerhetstekniker', 'Ditt tekniska intresse i kombination med strukturerat arbetssätt och en viss operativ läggning matchar arbetet med att installera, driftsätta och underhålla säkerhetssystem.', 'Your technical interest combined with structured working and some operational bent matches installing, commissioning and maintaining security systems.', NULL, NULL)
